			}
			catch (IllegalArgumentException exception) {
				ProjectKorra.log.warning("Your current value for 'Properties.Water.WaterSound.Sound' is not valid.");
			}
			finally {
				loc.getWorld().playSound(loc, sound, volume, pitch);
			}
		}
